import hashlib,json
from pathlib import Path
import numpy as np
from geometry_msgs.msg import Transform
from multi_robot_exploration import control as c
p=Path('log/p3b5/p3b5_v34_fixed_lab101_ap_snapshots_qos_fixed/snapshots.jsonl')
evidence=[]
for record in (json.loads(x) for x in p.open()):
 if not 2320 < record['observer_time'] < 2370:continue
 m=record['messages'];g=m['map'];res=g['info']['resolution'];origin=tuple(g['info']['origin']['position'][k] for k in ('x','y'));raw=np.asarray(g['data']).reshape(g['info']['height'],g['info']['width'])
 positions={}
 for n in ('tb1','tb2','tb3'):
  t=m[n+'/tf']['transforms'][0]['transform'];tf=Transform()
  for k,v in t['translation'].items():setattr(tf.translation,k,v)
  for k,v in t['rotation'].items():setattr(tf.rotation,k,v)
  od=m[n+'/odom']['pose']['pose']['position'];positions[n]=c.transform_point_2d(od['x'],od['y'],tf)
 poses=json.loads(m['rally_assignments']['data'])['poses'];final={n:c.RallyPose(**pose) for n,pose in poses.items()}
 routes={n:(positions[n],*c.plan_rally_leg(final[n],raw,res,origin,positions[n])[1]) for n in positions}
 plan=c.plan_rally_leg(final['tb2'],raw,res,origin,positions['tb2'],5.,[v for n,v in positions.items() if n!='tb2'],visible_only=True)
 old=c.reserve_rally_prefix(plan,c.rally_priority_reservations(['tb3','tb2','tb1'],'tb2',routes,set()))
 new=c.reserve_rally_prefix(plan,c.rally_priority_reservations(['tb3','tb2','tb1'],'tb2',routes,{'tb3'}))
 evidence.append({'snapshot_time':record['observer_time'],'positions':positions,'plan_exists':plan[0] is not None,'old_admitted':old is not None,'donated_priority_admitted':new is not None})
r={'scope':'offline component replay, exact delivered assignment; order tb3,tb2,tb1 consistent with energy-ready stable sort but not directly recorded at snapshot; not alternate mission proof','snapshot_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'evidence':evidence}
Path('/tmp/p3b5_v34_recovery_replay.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r,indent=2))
